}

function buildMissingSetupItem(item) {
    var text = '* *' + (item.name || '?') + '*';
    if (item.description) {
        text += ': ' + item.description;
    }
    text += '\n';
    if (item.how_to_add) {
        text += '{code:bash}' + item.how_to_add + '{code}\n';
    }
    return text;
}

function buildBlockedComment(result, prUrl) {
    var comment = 'h3. 🚫 Test Automation Blocked — Awaiting Human Setup\n\n';
