function buildPRReworkComment(ticketKey, testStatus, passed, prBodyContent) {
    const statusEmoji = passed ? '✅' : '❌';
    return '## 🔧 Test Rework Complete — ' + ticketKey + '\n\n' +
        '**Re-run result**: ' + statusEmoji + ' ' + testStatus.toUpperCase() + '\n\n' +
