function resultBelongsToTicket(parsed, ticketKey) {
    if (!parsed || typeof parsed !== 'object') return true;
    var keys = [parsed.ticketKey, parsed.storyKey, parsed.testCaseKey, parsed.issueKey];
    for (var i = 0; i < keys.length; i++) {
