/**
 * Post Test Automation Results Action (postJSAction for test_case_automation)
 * 1. Reads outputs/test_automation_result.json
 * 2. Stages testing/ folder, commits, pushes, creates PR to main
 * 3. Posts tracker comment from outputs/tracker_comment.md (fallback: comment.md, jira_comment.md)
 * 4. If passed:          moves ticket to In Review - Passed
 * 5. If failed:          moves Test Case to In Review - Failed (bug created by bug_creation agent on Failed)
 * 6. If blocked_by_human: moves ticket to Blocked, posts what credentials/data are needed,
 *                         removes SM trigger label so ticket is re-processed after human fix
 * 7. Removes WIP label
 */

var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');
var autoStart = require('./common/autoStart.js');
const { GIT_CONFIG, LABELS } = require('./config.js');
var outputFiles = require('./common/outputFiles.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var trackersModule = require('./common/trackers.js');
var postHelpers = require('./postTestAutomationResultsHelpers.js');
// Tracker-agnostic ticket ops; (re)created inside action() so no tracker exists at module load.
var tracker = null;

function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function readFile(path) {
    return outputFiles.readOutputFile(path, {});
}

function readOutputFile(relativePath, workingDir, ticketKey) {
    return outputFiles.readOutputFile(relativePath, {
        workingDir: workingDir,
        ticketKey: ticketKey
    });
}

function resultBelongsToTicket(parsed, ticketKey) {
    if (!parsed || typeof parsed !== 'object') return true;
    var keys = [parsed.ticketKey, parsed.storyKey, parsed.testCaseKey, parsed.issueKey];
    for (var i = 0; i < keys.length; i++) {
        if (keys[i] && keys[i] !== ticketKey) {
            console.warn('outputs/test_automation_result.json belongs to ' + keys[i] + ', not ' + ticketKey + ' — treating as stale');
            return false;
        }
    }
    return true;
}

function readResultJson(workingDir, ticketKey) {
    try {
        const raw = readOutputFile('test_automation_result.json', workingDir, ticketKey);
        if (!raw) {
            console.warn('outputs/test_automation_result.json is empty or missing');
            return null;
        }
        const parsed = JSON.parse(raw);
        if (!resultBelongsToTicket(parsed, ticketKey)) {
            return null;
        }
        console.log('Test result status:', parsed.status);
        return parsed;
    } catch (e) {
        console.error('Failed to parse test_automation_result.json:', e);
        return null;
    }
}

function markdownToJiraWiki(markdown) {
    if (!markdown) return '';

    var text = String(markdown);

    text = text.replace(/```(\w+)?\n([\s\S]*?)```/g, function(_, language, code) {
        return '{code' + (language ? ':' + language : '') + '}\n' + code.trim() + '\n{code}';
    });

    text = text
        .replace(/^####\s+(.+)$/gm, 'h4. $1')
        .replace(/^###\s+(.+)$/gm, 'h3. $1')
        .replace(/^##\s+(.+)$/gm, 'h2. $1')
        .replace(/^#\s+(.+)$/gm, 'h1. $1')
        .replace(/^\s*-\s+/gm, '* ')
        .replace(/\*\*([^*\n]+)\*\*/g, '*$1*')
        .replace(/`([^`\n]+)`/g, '{{$1}}')
        .replace(/\[([^\]\n]+)\]\((https?:\/\/[^)\s]+)\)/g, '[$1|$2]');

    return text.trim();
}

function readJiraComment(params, workingDir, ticketKey) {
    var jiraComment = readOutputFile('tracker_comment.md', workingDir, ticketKey);
    if (jiraComment) return jiraComment;

    jiraComment = readOutputFile('comment.md', workingDir, ticketKey);
    if (jiraComment) return jiraComment;

    jiraComment = readOutputFile('jira_comment.md', workingDir, ticketKey);
    if (jiraComment) return jiraComment;

    return markdownToJiraWiki(params.response || readOutputFile('response.md', workingDir, ticketKey) || '');
}

function runInRepo(command, workingDir) {
    var args = { command: command };
    if (workingDir) args.workingDirectory = workingDir;
    return cli_execute_command(args);
}

function fetchRemoteBranch(branchName, workingDir) {
    try {
        runInRepo('git fetch origin ' + branchName, workingDir);
        return true;
    } catch (e) {
        console.warn('Could not fetch remote branch origin/' + branchName + ':', e);
        return false;
    }
}

function revParse(ref, workingDir) {
    try {
        return cleanCommandOutput(runInRepo('git rev-parse ' + ref, workingDir) || '').trim();
    } catch (e) {
        return '';
    }
}

function findMergeBase(left, right, workingDir) {
    try {
        return cleanCommandOutput(runInRepo('git merge-base ' + left + ' ' + right, workingDir) || '').trim();
    } catch (e) {
        return '';
    }
}

function publishExistingBranch(branchName, workingDir) {
    // Ensure the local remote-tracking ref is fresh before any push decision.
    fetchRemoteBranch(branchName, workingDir);

    var localSha = revParse('HEAD', workingDir);
    var remoteSha = revParse('origin/' + branchName, workingDir);

    // The identical check must stay BEFORE the merge-base call: when the
    // branch is already in sync no `git merge-base` command may run.
    var strategy;
    if (localSha && remoteSha && localSha === remoteSha) {
        strategy = 'identical';
    } else {
        var mergeBase = (localSha && remoteSha) ? findMergeBase('HEAD', 'origin/' + branchName, workingDir) : '';
        // gh-1043: pure decision extracted (and unit-tested) in postHelpers —
        // the strategies below keep the original command order and log lines.
        strategy = postHelpers.decidePublishStrategy(localSha, remoteSha, mergeBase);
    }

    if (strategy === 'identical') {
        console.log('Local branch already matches origin/' + branchName + '; no push needed');
        return { success: true, noNewCommit: true };
    }

    if (strategy === 'ahead') {
        // Local is strictly ahead of remote (fast-forward).
        try {
            runInRepo('git push -u origin ' + branchName, workingDir);
            return { success: true, noNewCommit: true };
        } catch (e) {
            console.warn('Fast-forward push failed:', e);
        }
    } else if (strategy === 'behind') {
        // Remote moved ahead while we had no local changes to keep. Adopt remote state.
        console.log('Remote ' + branchName + ' is ahead of local branch; resetting to origin/' + branchName);
        runInRepo('git reset --hard origin/' + branchName, workingDir);
        return { success: true, noNewCommit: true };
    }

    // Branches diverged or no remote yet; fall back to push with refreshed lease.
    try {
        runInRepo('git push -u origin ' + branchName, workingDir);
        return { success: true, noNewCommit: true };
    } catch (pushErr) {
        console.log('Normal push failed, retrying with --force-with-lease...');
        try {
            runInRepo('git push -u origin ' + branchName + ' --force-with-lease', workingDir);
            return { success: true, noNewCommit: true };
        } catch (forcePushErr) {
            console.warn('Failed to publish existing branch:', forcePushErr);
            return { success: false, error: 'No test files were written and the synced branch could not be pushed' };
        }
    }
}

function performGitOperations(branchName, commitMessage, workingDir, testFilesPath) {
    var addPath = testFilesPath || 'testing/';
    var inspectPath = addPath.replace(/\/$/, '') || '.';
    try {
        // Diagnostic: list test files before staging
        try {
            var lsOutput = runInRepo('git status --short -- ' + inspectPath, workingDir) || '';
            console.log('Git status for ' + inspectPath + ':', cleanCommandOutput(lsOutput) || '(empty)');
        } catch (e) {
            console.warn('Could not list ' + inspectPath + ':', e);
        }

        // Stage the configured test path only (outputs/ is gitignored — test artifacts should not be committed)
        console.log('Staging test path:', addPath);
        runInRepo('git add ' + addPath, workingDir);

        // Check for STAGED ch…

/**
 * Pure helpers for js/postTestAutomationResults.js (gh-961).
 *
 * Every function here is side-effect free: string building and pure
 * decisions extracted from action() so the orchestration function shrinks
 * below the CRAP threshold. Strings must stay byte-identical to the
 * originals — they are posted verbatim to the tracker.
 */

function parseOutcome(result) {
    var status = ((result && result.status) || '').toLowerCase();
    return {
        status: status,
        passed: status === 'passed',
        blockedByHuman: status === 'blocked_by_human'
    };
}

function decideWipLabel(metadata) {
    return metadata && metadata.contextId
        ? metadata.contextId + '_wip'
        : 'test_case_automation_wip';
}

function decideSmTriggerLabel(params) {
    var customParams = params.jobParams && params.jobParams.customParams;
    return (customParams && customParams.removeLabel) || null;
}

function buildMissingResultComment(partialPushed) {
    var comment = 'h3. ⚠️ Test Automation Error\n\nCLI exited without producing result JSON (likely hit rate limit or crashed).\n';
    if (partialPushed) {
        comment += 'Partial code was pushed to the branch — next retry will continue from there.\n';
    }
    comment += 'Ticket moved back to *Backlog* so SM can retry.';
    return comment;
}

function buildMissingSetupItem(item) {
    var text = '* *' + (item.name || '?') + '*';
    if (item.description) {
        text += ': ' + item.description;
    }
    text += '\n';
    if (item.how_to_add) {
        text += '{code:bash}' + item.how_to_add + '{code}\n';
    }
    return text;
}

function buildBlockedComment(result, prUrl) {
    var comment = 'h3. 🚫 Test Automation Blocked — Awaiting Human Setup\n\n';
    if (result.blocked_reason) {
        comment += result.blocked_reason + '\n\n';
    }
    if (result.missing && result.missing.length > 0) {
        comment += 'h4. Required setup:\n\n';
        for (var i = 0; i < result.missing.length; i++) {
            comment += buildMissingSetupItem(result.missing[i]);
        }
    }
    if (prUrl) {
        comment += '\n*Test Branch PR* (test code is ready, skips without credentials): ' + prUrl;
    }
    comment += '\n\nOnce setup is complete, move this ticket back to *Backlog* to trigger re-run.';
    return comment;
}

function buildFinalComment(jiraComment, prUrl, noCodeChanges) {
    var comment = jiraComment || '';
    if (prUrl) {
        comment += '\n\n*Test Branch PR*: ' + prUrl;
    }
    if (noCodeChanges) {
        comment += '\n\nℹ️ _Test code unchanged from previous run — PR review step skipped._';
    }
    return comment;
}

function buildPrFailureComment(branchName, error) {
    return 'h3. ⚠️ PR Creation Failed\n\nTest code was pushed to branch {code}' + branchName +
        '{code} but the Pull Request could not be created.\n\n' +
        'Ticket moved back to *Backlog* — will be re-processed automatically. The next run will detect the existing branch and create the PR.\n\n' +
        'Error: ' + (error || 'unknown');
}

function buildGitFailureComment(error) {
    return 'h3. ⚠️ Git Operations Failed\n\nFailed to commit/push test code: ' + error +
        '\n\nTicket moved back to *Backlog* — will be re-processed automatically.';
}

function buildConflictComment(branchName, baseBranch, prUrl) {
    return 'h3. 🚫 Test Automation Blocked — PR Conflicts With Main\n\n' +
        'The test automation branch {code}' + branchName + '{code} still conflicts with {code}' + baseBranch + '{code} after the agent run.\n\n' +
        '*Pull Request:* ' + prUrl + '\n\n' +
        'A {code}merge_conflicts.md{code} guidance file was present for this run, which means the existing test branch could not be safely auto-aligned with {code}origin/' + baseBranch + '{code}. ' +
        'Do not send this PR into automated review until the branch is deliberately synced with main and only ticket-specific test automation changes remain.\n\n' +
        'Ticket moved to *Blocked* for human conflict resolution.';
}

function buildErrorComment(error) {
    return 'h3. ❌ Test Automation Error\n\n{code}' + error.toString() + '{code}';
}

function buildPartialCommitMessage(baseMessage) {
    return baseMessage + ' (partial — CLI interrupted)';
}

function decideTargetStatus(passed, noCodeChanges, statuses) {
    if (passed) {
        return noCodeChanges
            ? { stage: 'PASSED', statusName: statuses.PASSED }
            : { stage: 'IN_REVIEW_PASSED', statusName: statuses.IN_REVIEW_PASSED };
    }
    return noCodeChanges
        ? { stage: 'FAILED', statusName: statuses.FAILED }
        : { stage: 'IN_REVIEW_FAILED', statusName: statuses.IN_REVIEW_FAILED };
}

/**
 * Pure sync-strategy decision for publishExistingBranch from the three known
 * revisions (gh-1043 CRAP split). Mirrors the original in-function conditions
 * EXACTLY — including the empty-string edge cases (a failed rev-parse yields
 * ''), because the command sequence and log lines differ per strategy:
 * 'identical' | 'ahead' (fast-forward push, then fall through to the
 * diverged escalation when the push fails) | 'behind' (reset --hard) |
 * 'diverged' (normal push → --force-with-lease escalation).
 */
function decidePublishStrategy(localSha, remoteSha, mergeBase) {
    if (localSha && remoteSha && localSha === remoteSha) return 'identical';
    if (mergeBase === remoteSha && mergeBase !== localSha) return 'ahead';
    if (mergeBase === localSha && mergeBase !== remoteSha) return 'behind';
    return 'diverged';
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        parseOutcome: parseOutcome,
        decideWipLabel: decideWipLabel,
        decideSmTriggerLabel: decideSmTriggerLabel,
        buildMissingResultComment: buildMissingResultComment,
        buildMissingSetupItem: buildMissingSetupItem,
        buildBlockedComment: buildBlockedComment,
        buildFinalComment: buildFinalComment,
        buildPrFailureComment: buildPrFailureComment,
        buildGitFailureComment: buildGitFailureComment,
        buildConflictComment: buildConflictComment,
        buildErrorComment: buildErrorComment,
        buildPartialCommitMessage: buildPartialCommitMessage,
        decideTargetStatus: decideTargetStatus,
        decidePublishStrategy: decidePublishStrategy
    };
}

/**
 * Post Test Rework Results Action (postJSAction for pr_test_automation_rework)
 * After cursor agent fixes test issues and re-runs the test:
 * 1. Reads outputs/test_automation_result.json (new test result after fixes)
 * 2. Stages testing/ folder, commits, force-pushes to existing PR branch
 * 3. Replies to and resolves PR review threads (from outputs/review_replies.json)
 * 4. Posts PR comment with fix summary
 * 5. If test passed  → moves to In Review - Passed
 * 6. If test failed  → moves to In Review - Failed (bug may have changed)
 * 7. Posts Jira comment, removes WIP label
 *
 * gh-928: the action orchestration was split into pure planners/parsers
 * (normalizeTestStatus, buildResultErrorMessage, buildPRReworkComment,
 * buildAutoPRTitle, prNumberFromUrl, buildFallbackPR, prMatchesBranch) and
 * thin executors (runPublishGates, releaseReworkLock, postReworkBodyAndComment,
 * handleReplyItem, triggerAutoStart, resumeOrReport). Side effects, call order,
 * log lines and result shapes are unchanged — characterization-tested by
 * js/unit-tests/test_postTestReworkResults.js.
 */

var configLoader = require('./configLoader.js');
var autoStart = require('./common/autoStart.js');
var feedbackLoop = require('./common/feedbackLoop.js');
var prHelper = require('./common/pullRequest.js');
var mergeState = require('./common/mergeState.js');
const { GIT_CONFIG, LABELS } = require('./config.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var trackersModule = require('./common/trackers.js');
var commentMarkup = require('./common/commentMarkup.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}


/**
 * Build the "Test Rework Completed" comment in the flavor of the ticket's
 * tracker (gh-770). The template historically hard-coded Jira wiki markup
 * (h3., *bold*, {code}) and was posted via raw jira_post_comment; on a
 * GitHub-backed tracker that renders as raw text garbage.
 *
 * @param {Object} flavor - a commentMarkup flavor bag (forTicket/forFlavor)
 * @param {Object} ctx    - { passed, testStatus, branchName, prUrl, fixSummary }
 * @returns {string} the rendered comment
 */
function buildTestReworkResultComment(flavor, ctx) {
    var m = flavor;
    var statusEmoji = ctx.passed ? '✅' : '❌';
    var comment = m.h(3, '🔧 Test Rework Completed') + '\n\n' +
        m.bold('Re-run result') + ': ' + statusEmoji + ' ' + m.bold(String(ctx.testStatus).toUpperCase()) + '\n' +
        m.bold('Branch') + ': ' + m.inline(ctx.branchName) + '\n';
    if (ctx.prUrl) {
        comment += m.bold('Pull Request') + ': ' + ctx.prUrl + '\n';
    }
    comment += '\n' + ctx.fixSummary;
    return comment;
}

// Canonical copy (gh-823/gh-912): the warning:/note: line filter lives in
// common/pullRequest.js once — this delegate keeps every local call site.
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function readFile(path) {
    try {
        const content = file_read({ path: path });
        return (content && content.trim()) ? content : null;
    } catch (e) {
        console.warn('Could not read file ' + path + ':', e);
        return null;
    }
}

function readResultJson() {
    try {
        const raw = readFile('outputs/test_automation_result.json');
        if (!raw) return null;
        return JSON.parse(raw);
    } catch (e) {
        console.error('Failed to parse test_automation_result.json:', e);
        return null;
    }
}

function findTestPRForTicket(scm, ticketKey) {
    try {
        const branchName = 'test/' + ticketKey;
        const openPRs = scm.listPrs('open') || [];
        const match = openPRs.filter(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName;
        });
        if (match.length > 0) return match[0];
        console.warn('No open test PR found for branch', branchName);
        return null;
    } catch (e) {
        console.error('Failed to find PR:', e);
        return null;
    }
}

// ── gh-928 pure planners/parsers ─────────────────────────────────────────────

/**
 * Normalize a raw test-result status into the canonical passed/failed token.
 * Anything else is returned verbatim (the workflow treats it as not-passed).
 */
function normalizeTestStatus(rawStatus) {
    return (rawStatus === 'pass' || rawStatus === 'passed') ? 'passed' :
           (rawStatus === 'fail' || rawStatus === 'failed') ? 'failed' :
           rawStatus;
}

/**
 * The operator-facing message for an unreadable/invalid rework result JSON.
 * Distinguishes "file missing or empty" from "present but no status field".
 */
function buildResultErrorMessage(result) {
    return !result
        ? 'Could not read outputs/test_automation_result.json — file missing or empty.'
        : 'outputs/test_automation_result.json is missing required "status" field (got: ' + JSON.stringify(result) + '). The agent must write { "status": "passed" | "failed", ... }.';
}

/** The rework WIP label follows the workflow context when one is declared. */
function resolveWipLabel(actualParams) {
    return actualParams.metadata && actualParams.metadata.contextId
        ? actualParams.metadata.contextId + '_wip'
        : 'pr_test_automation_rework_wip';
}

/** Whether an open-PR list entry points at the given branch. */
function prMatchesBranch(pr, branchName) {
    return pr.head && pr.head.ref === branchName;
}

/** "KEY Summary" title for an auto-created rework PR, degrading to the key. */
function buildAutoPRTitle(ticket, ticketKey) {
    const summary = ticket && ticket.fields ? (ticket.fields.summary || ticketKey) : ticketKey;
    return ticketKey + ' ' + summary;
}

/** Best-effort PR number from a GitHub compare URL; null when not parseable. */
