        var mergeCalls = cli.calls.filter(function(c) {
            return c.indexOf('git merge origin/main') === 0;
        });
        assert.ok(mergeCalls.length > 0,
            'prIsDirty + no merge in progress → base-branch merge must be started');
    });

});

