        assert.ok(updated, 'should rewrite outputs/pr_feature_update.md');
        assert.ok(updated.indexOf('All passed') !== -1, 'should keep original content');
        assert.ok(updated.indexOf('> Automation PR: ' + AUTOMATION_PR_URL) !== -1,
