        var cli = makeCli({});
        var m = loadPostTestReworkResults(cli);

        m.commitIfNeeded('PROJ-123', true, REWORK_CONFIG);

        assert.ok(cli.calls.some(function(c) {
            return c.indexOf('git rev-parse --quiet --verify MERGE_HEAD') !== -1;
