            assert.equal(ctx.actualParams, inner, 'actualParams is the jobParams body');
            assert.equal(ctx.ticketKey, 'PROJ-78');
        });

        test('unwrapped shape without jobParams.ticket falls back to params itself', function() {
            var m = helperModule();
            var params = { ticket: { key: 'PROJ-79' } };
