/**
 * Unit tests for js/postMobileTestAutomationResults.js
 *
 * Tests: findFeaturePR (parseMcpResult), updateFeaturePRBody (github_add_pr_comment),
 *        updateFeaturePRLabel (tests_passed/tests_failed), full action flow.
