                if (opts.path === 'outputs/pr_feature_update.md') return '## Test Results\n\nAll passed ✅';
                if (opts.path.indexOf('.dmtools/config') !== -1) return null;
                return null;
            },
            file_write: function(path, content) {
                writes[path] = content;
            },
