        var calls = [];
        var m = loadPostCli({
            github_remove_pr_label: function(opts) { calls.push(['remove', opts]); },
            github_add_pr_label: function(opts) { calls.push(['add', opts]); }
        });

        m.updateFeaturePRLabel('ExampleOrg', 'example-mobile-app', 963, true, 'tests_passed', 'tests_failed');

