function parse(p) {
  const rows = fs.readFileSync(p, 'utf8').split('\n').slice(4);
  const map = {};
  for (const line of rows) {
    const m = line.match(/^(.+?)\s{2,}(\S+)\s+(\d+)\s+([\d.]+%|N\/A)\s+([\d.]+|N\/A)\s*$/);
    if (!m) continue;
    const key = m[2].trim() + '::' + m[1].trim();
    map[key] = { cc: +m[3], cov: m[4], crap: m[5] === 'N/A' ? null : parseFloat(m[5]) };
  }
  return map;
}
